// fld + fstp of the same width: the bits as x87 stores them back (a signaling NaN gets its quiet bit). Integers only, so no x87
// return register touches the value (c3fe_x87load).
void c3fl_x87move64(void* dst, const void* src) {
    uint64_t b = *static_cast<const uint64_t*>(src);
    if ((b & 0x7ff0000000000000ull) == 0x7ff0000000000000ull && (b & 0x000fffffffffffffull) && !(b & 0x0008000000000000ull))
        b |= 0x0008000000000000ull;
    *static_cast<uint64_t*>(dst) = b;
}
unsigned c3fl_x87load32(const void* src) {
    unsigned b = *static_cast<const unsigned*>(src);
    if ((b & 0x7f800000u) == 0x7f800000u && (b & 0x007fffffu) && !(b & 0x00400000u)) b |= 0x00400000u;
    return b;
}

// The doubly linked node list {+0 head, +4 tail, +8 cursor, +0xc count} of nodes {+0 prev, +4 next, +8 object} that flushSoundList
// (0x10008559-0x100085af) and Midi_Device::dispatchCommand (0x1000a720-0x1000a775, 0x1000a7a5-0x1000a810) unlink an object from:
// the first node whose object is `obj` (searched from the head); prev->next = next or head = next; next->prev = prev with the
// cursor = next, or (no next) cursor = 0 and tail = prev; the node goes to operator delete and the count drops by one.
void c3fl_unlinkObject(char* list, void* obj) {
    char* n = fat<char*>(list, 0);
    while (n && fat<void*>(n, 8) != obj) n = fat<char*>(n, 4);
    if (!n) return;
    char* prev = fat<char*>(n, 0);
    if (prev) fat<char*>(prev, 4) = fat<char*>(n, 4);
    else fat<char*>(list, 0) = fat<char*>(n, 4);
    char* next = fat<char*>(n, 4);
    if (next) {
        fat<char*>(next, 0) = fat<char*>(n, 0);
        fat<char*>(list, 8) = next;
    } else {
        fat<char*>(list, 8) = 0;
        fat<char*>(list, 4) = fat<char*>(n, 0);
    }
    c3fl_delete(n);
    fat<int>(list, 0xc) -= 1;
}

