    if (r == 0) return 0;                                                     // 0x100101cf / 0x100101d1
    if (!c3fl_isBufferLost(r)) return 0x19;                                   // -> 0x10010251
    buf = fat<void*>(self, 0x60);                                             // 0x100101f7
