            if (tune)
                c3fl_th1(0x000026e4, reinterpret_cast<void*>(b), fat<unsigned>(fat<char*>(ch, 0x54), 0xc4));   // 0x1003451d-0x1003452b
            c3fl_th1(0x00001181, reinterpret_cast<void*>(b), fat<unsigned>(ch, 0x220));   // 0x10034530-0x1003453b
            if (fat<unsigned char>(ch, 0x5c) & 0x20) {                        // 0x10034540 / 0x10034544
                char* src = fat<char*>(ch, 0x54);                             // 0x10034546
                c3fl_th3(0x00001889, reinterpret_cast<void*>(b), c3fl_x87load32(src + 0xc8), c3fl_x87load32(src + 0xcc),
                         c3fl_x87load32(src + 0xd0));                         // 0x10034549-0x1003456b
            }
            unsigned n22c = fat<unsigned>(ch, 0x22c);                         // 0x10034570
            if (n22c == 0) c3fl_th1(0x00001203, reinterpret_cast<void*>(b), 0);   // 0x1003457a-0x1003457f
            else fat<unsigned>(reinterpret_cast<char*>(b), 0x44) = 0u - n22c;  // 0x10034594-0x1003459b
            fat<unsigned>(ch, 0x58) &= 0xffffffefu;                           // 0x10034584-0x1003458a / 0x1003459e-0x100345a3
            return 0;
