        unsigned i = 0, bit = 1;                                              // 0x10034481 / 0x10034483
        unsigned hi = f58 >> 12;                                              // 0x100345ad
        while ((hi & bit & 0xffff) != 0) {                                    // 0x100345b0-0x100345ba
            bit <<= 1;                                                        // 0x100345bc
            if (++i >= 0x10) break;                                           // 0x100345be-0x100345c2
        }
        if (i == 0x10) return 6;                                              // 0x100345c4-0x100345cc
        char* r = ch + i * 0x110;                                             // 0x100345d4-0x100345de
        fat<unsigned>(r, 0x2c0) = 0;                                          // 0x100345e8
        fat<unsigned>(r, 0x254) = fat<unsigned>(r, 0x250);                    // 0x100345e1 / 0x100345ee
        unsigned char d4 = fat<unsigned char>(r, 0x2d4) & 0xf1;               // 0x100345f4 / 0x100345fa
        fat<unsigned>(r, 0x2c4) = 0;                                          // 0x100345fd
        fat<unsigned char>(r, 0x2d4) = d4;                                    // 0x10034603
        fat<unsigned>(r, 0x328) = fat<unsigned>(r, 0x330);                    // 0x10034609 / 0x1003460f
        fat<unsigned>(r, 0x2f8) = 0;                                          // 0x1003461b
        fat<unsigned>(r, 0x32c) = fat<unsigned>(r, 0x334);                    // 0x10034615 / 0x10034621
        c3fl_x87move64(r + 0x2b8, ch + 0x1f0);                                // 0x10034627 / 0x1003462d
        c3fl_x87move64(r + 0x2a8, ch + 0x200);                                // 0x10034633 / 0x10034639
        c3fl_x87move64(r + 0x340, ch + 0x1388);                               // 0x1003463f / 0x10034645
        c3fl_x87move64(r + 0x290, ch + 0x1e0);                                // 0x1003464b / 0x10034651
        fat<unsigned>(r, 0x2fc) = fat<unsigned>(ch, 0x22c);                   // 0x10034657 / 0x1003465d
        fat<unsigned>(r, 0x2f8) = 0;                                          // 0x10034669
        fat<char*>(r, 0x300) = ch + 0x230;                                    // 0x10034663 / 0x1003466f
        fat<unsigned char>(r, 0x2d4) &= 0xfb;                                 // 0x10034675-0x1003467e
